/** Native history can prove a completed boundary without inventing application graph nodes. */
export const ProviderNativeCompletedTurnRef = Schema.Struct({
  driver: ProviderDriverKind,
  nativeId: Schema.String,
  strength: Schema.Literal("strong"),
});
export type ProviderNativeCompletedTurnRef = typeof ProviderNativeCompletedTurnRef.Type;

export const ProviderNativeHistoryBoundary = Schema.Struct({
  nativeSessionId: Schema.String,
  completedTurnRefs: Schema.Array(ProviderNativeCompletedTurnRef),
  /** Explicit current completed native tip; array order alone never establishes a head. */
  latestCompletedTurnRef: Schema.optionalKey(ProviderNativeCompletedTurnRef),
});
export type ProviderNativeHistoryBoundary = typeof ProviderNativeHistoryBoundary.Type;
